def solve_game(N):
    # Win[n] is True if the player whose turn it is at number n wins, False otherwise.
    win = [False] * (N + 1)

    for n in range(N - 1, 0, -1):
        next_moves = []

        if n + 1 <= N:
            next_moves.append(n + 1)

        if 2 * n <= N:
            next_moves.append(2 * n)

        can_win = False
        for m in next_moves:
            if m == N:
                can_win = True
                break
            elif m < N and not win[m]:
                can_win = True
                break

        win[n] = can_win

    return win[1]

