def solve_game(N):
    # S[n] will store the status of position n. True = N-position (Win), False = P-position (Loss).
    # We only care about n from 1 to N-1.
    if N < 2:
        return None

    S = {} # Use a dictionary for sparse storage if N is large, but N is bounded in this task.

    # Base case: N is the winning target.

    # Iterate backwards from N-1 down to 1
    for n in range(N - 1, 0, -1):

        can_win = False

        # Check move n+1
        next_1 = n + 1
        if next_1 <= N:
            if next_1 == N:
                # Direct win
                can_win = True
            else:
                # Check if the resulting position is a P-position (Loss for opponent)
                # If S[next_1] is False (Loss for player starting there), then n is a winning move.
                if S[next_1] is False:
                    can_win = True

        # Check move 2n
        next_2 = 2 * n
        if not can_win and next_2 <= N:
            if next_2 == N:
                # Direct win
                can_win = True
            else:
                # Check if the resulting position is a P-position (Loss for opponent)
                if S[next_2] is False:
                    can_win = True

        S[n] = can_win

    # The status of N is Type A if S[1] is True (N-position), Type B if S[1] is False (P-position).
    return S[1]

